#include <bits/stdc++.h>
using namespace std;

struct Rectangle {
    int x1, y1, x2, y2;
};

vector<unsigned char> buildCoveredEdges(
    int nx, int ny, const vector<Rectangle>& rects, bool horizontal
) {
    vector<int> diff(static_cast<size_t>(nx) * ny, 0);

    auto add = [&](int r, int c, int value) {
        if (r >= 0 && r < ny && c >= 0 && c < nx)
            diff[static_cast<size_t>(r) * nx + c] += value;
    };

    for (const auto& r : rects) {
        int r1, c1, r2, c2;
        if (horizontal) {
            if (r.x1 == r.x2) continue;
            r1 = r.y1;
            r2 = r.y2;
            c1 = r.x1;
            c2 = r.x2 - 1;
        } else {
            if (r.y1 == r.y2) continue;
            r1 = r.y1;
            r2 = r.y2 - 1;
            c1 = r.x1;
            c2 = r.x2;
        }

        add(r1, c1, 1);
        add(r2 + 1, c1, -1);
        add(r1, c2 + 1, -1);
        add(r2 + 1, c2 + 1, 1);
    }

    int rows = horizontal ? ny : ny - 1;
    int cols = horizontal ? nx - 1 : nx;
    vector<unsigned char> covered(static_cast<size_t>(rows) * cols);

    for (int r = 0; r < ny; ++r) {
        for (int c = 0; c < nx; ++c) {
            size_t id = static_cast<size_t>(r) * nx + c;
            int value = diff[id];
            if (r > 0) value += diff[id - nx];
            if (c > 0) value += diff[id - 1];
            if (r > 0 && c > 0) value -= diff[id - nx - 1];
            diff[id] = value;

            if (r < rows && c < cols)
                covered[static_cast<size_t>(r) * cols + c] = (value > 0);
        }
    }

    return covered;
}

